export const EVENT_CLICK = 7
/** Each event's name, by its number. */
export const EVENTS = ['POINTER_DOWN', 'POINTER_MOVE', 'POINTER_UP', 'POINTER_CANCEL', 'KEY_DOWN', 'KEY_UP', 'BLUR', 'CLICK'] as const

/** The effect `act`. */
export const EFFECT_ACT = 0
/** The effect `press`. */
export const EFFECT_PRESS = 1
/** The effect `hold`. */
export const EFFECT_HOLD = 2
/** The effect `deadline`. */
export const EFFECT_DEADLINE = 3
/** The effect `deadline-end`. */
export const EFFECT_DEADLINE_END = 4
/** Each effect's name, by its number. */
export const EFFECTS = ['act', 'press', 'hold', 'deadline', 'deadline-end'] as const

/** The request event `click`. */
export const ASK_CLICK = 0
/** Each request event's name, by its number. */
export const ASKS = ['click'] as const

/** A literal an effect is given. */
export type Argument = Readonly<Record<string, boolean | number | string>>

/** An effect the host performs: its number, and its argument where it has one. */
export type Effect = readonly [effect: number, argument?: Argument]

/** A move: the state it leaves the machine in, the context after it, and the effects it runs, in order. */
export interface Move {
  readonly context: PressContext
  readonly effects: readonly Effect[]
  readonly state: number
}

/** A request: the events the host asks with first, in order, and the move for each outcome. */
export interface Asking {
  readonly accept: Move
  readonly ask: readonly number[]
  readonly refuse: Move
}

/** The state the machine is in, read from its context. */
export const start = (_context: PressContext): number =>
  STATE_PART__SPACEUP__POINTERUP

/** The effects of starting in a state, as a host that mounts the machine runs them. */
export const entering = (state: number): readonly Effect[] => {
  switch (state) {
    case STATE_PART__SPACEUP__TIMING:
      return [[EFFECT_DEADLINE, { ms: 500, owner: 5 }]]
    case STATE_PART__SPACING__TIMING:
      return [[EFFECT_DEADLINE, { ms: 500, owner: 5 }]]
  }
  return []
}

/** What `part(spaceUp, pointerUp)` does with each event. */
const inPartSpaceupPointerup = (context: PressContext, event: number, input: PressInput): Move | Asking | undefined => {
  switch (event) {
    case EVENT_POINTER_DOWN:
      return startsHold(context, input) ? { context: beginHold(context, input), effects: [[EFFECT_DEADLINE, { ms: 500, owner: 5 }]], state: STATE_PART__SPACEUP__TIMING } : starts(context, input) ? { context: beginPress(context, input), effects: [], state: STATE_PART__SPACEUP__POINTING } : enabled(context) ? { context: notePointer(context, input), effects: [], state: STATE_PART__SPACEUP__POINTERUP } : undefined
    case EVENT_KEY_DOWN:
      return enterClaimed(context, input) ? { context: enterTaken(context), effects: [], state: STATE_PART__SPACEUP__POINTERUP } : enterClicks(context, input) ? { accept: { context: byEnter(context), effects: [[EFFECT_ACT], [EFFECT_PRESS]], state: STATE_PART__SPACEUP__POINTERUP }, ask: [ASK_CLICK], refuse: { context: noteKey(context), effects: [], state: STATE_PART__SPACEUP__POINTERUP } } : space(context, input) ? { context: noteKey(context), effects: [], state: STATE_PART__SPACING__POINTERUP } : enterKey(context, input) ? { context: noteKey(context), effects: [], state: STATE_PART__SPACEUP__POINTERUP } : undefined
    case EVENT_CLICK:
      return claims(context) ? { context: dropClaim(context), effects: [], state: STATE_PART__SPACEUP__POINTERUP } : ready(context) ? { accept: { context: byClick(context, input), effects: [[EFFECT_ACT], [EFFECT_PRESS]], state: STATE_PART__SPACEUP__POINTERUP }, ask: [ASK_CLICK], refuse: { context: context, effects: [], state: STATE_PART__SPACEUP__POINTERUP } } : undefined
  }
  return undefined
}

