/**
 * What an event does in a state: a move, a request, or `undefined` where the
 * state ignores it.
 */
export const step = (state: number, context: PressContext, event: number, input: PressInput): Move | Asking | undefined => {
  switch (state) {
    case STATE_PART__SPACEUP__POINTERUP:
      return inPartSpaceupPointerup(context, event, input)
    case STATE_PART__SPACEUP__POINTING:
      return inPartSpaceupPointing(context, event, input)
    case STATE_PART__SPACEUP__TIMING:
      return inPartSpaceupTiming(context, event, input)
    case STATE_PART__SPACING__POINTERUP:
      return inPartSpacingPointerup(context, event, input)
    case STATE_PART__SPACING__POINTING:
      return inPartSpacingPointing(context, event, input)
    case STATE_PART__SPACING__TIMING:
      return inPartSpacingTiming(context, event, input)
  }
  return undefined
}

/**
 * The move a state's deadline makes when it ends, or `undefined` where the
 * state `owner` names is not active in `state`.
 */
export const expire = (state: number, context: PressContext, owner: number): Move | undefined => {
  switch (state) {
    case STATE_PART__SPACEUP__TIMING:
      return owner === 5 ? { context: claimClick(context), effects: [[EFFECT_DEADLINE_END, { owner: 5 }], [EFFECT_HOLD]], state: STATE_PART__SPACEUP__POINTING } : undefined
    case STATE_PART__SPACING__TIMING:
      return owner === 5 ? { context: claimClick(context), effects: [[EFFECT_DEADLINE_END, { owner: 5 }], [EFFECT_HOLD]], state: STATE_PART__SPACING__POINTING } : undefined
  }
  return undefined
}

/** The move the machine's cancel makes from a state, where it has one. */
export const cancel = (_state: number, _context: PressContext): Move | undefined => undefined

/** The custom states a host records while the machine is in `state`. */
export const mark = (_state: number): readonly string[] => []
